changeSet.sql:
alter table r_ayrshare_company_config
    modify ayrshare_api_key varchar(64) default '' not null comment 'ayrshare平台API KEY；长度是冗余了一半';

alter table r_ayrshare_company_config
    modify ayrshare_domain varchar(128) default 'id-7f3ce' not null comment 'ayrshare平台domain';

alter table r_ayrshare_company_config
    modify ayrshare_profile_key varchar(64) default '' not null comment 'ayrshare的配置；长度是冗余了一半';

alter table r_ayrshare_company_config
    modify ayrshare_subreddit varchar(256) default 'recruit' not null comment 'reddit平台属性预留';

alter table r_ayrshare_company_config
    modify create_by_name varchar(64) default '' not null comment '创建人name';

alter table r_ayrshare_company_config
    modify update_by_name varchar(64) default '' not null comment '更新人name';

alter table r_ayrshare_company_config
    modify company_code varchar(64) default '' not null comment 'companyCode';
